INSERT INTO `products` VALUES (1,6,'มาม่า บะหมี่กึ่งสำเร็จรูป รสต้มยำกุ้ง 55 กรัม',7.00,'มาม่า บะหมี่กึ่งสำเร็จรูป รสต้มยำกุ้ง เส้นเหนียวนุ่ม น้ำซุปต้มยำรสชาติเข้มข้นถึงใจ','uploads/mama_tomyum_cup.png',100,''),(2,6,'ปลากระป๋องในซอสมะเขือเทศ ตราสามแม่ครัว (155 กรัม x 10 กระป๋อง)',195.00,'ปลากระป๋องสามแม่ครัว ผลิตจากปลาแมกเคอเรลเนื้อแน่น สด สะอาด ราดด้วยซอสมะเขือเทศเข้มข้นรสชาติกลมกล่อม เคียงคู่ครัวไทยมายาวนาน','uploads/three_maekrua.png',120,''),(3,6,'พาสต้าเส้นสปาเก็ตตี้ ตราแอคเนซี Agnesi Spaghetti No.3 (500 กรัม)',79.00,'สปาเก็ตตี้ แอคเนซี เบอร์ 3 ผลิตจากแป้งดูรัมเซโมลินาแท้ 100% ให้เส้นเหนียวนุ่ม อร่อยสไตล์อิตาเลียนแท้ๆ','uploads/spaghetti.png',80,''),(4,6,'ผงปรุงรสรสหมู ตราสุกรส้มดี (RosDee) (80 กรัม x 6 ซอง)',150.00,'ผงปรุงรส รสดี ช่วยปรุงแต่งรสชาติอาหารทุกเมนูให้อร่อยกลมกล่อม หอมกลิ่นกระเทียม พริกไทย และเครื่องเทศธรรมชาติ','uploads/rosdee_pork.png',100,''),(6,7,'โอวัลติน คูล ช็อกโกแลตมอลต์ (30 กรัม x 12 ซอง)',120.00,'เครื่องดื่มช็อกโกแลตมอลต์ปรุงสำเร็จ โอวัลติน คูล สูตรละลายในน้ำเย็น อร่อยเข้มข้น มีวิตามินและแร่ธาตุสูง','uploads/ovaltine_uht.png',90,''),(7,7,'นมถั่วเหลือง ยูเอชที แลคตาซอย รสออริจินัล (300 มล. x 6 กล่อง)',72.00,'นมถั่วเหลืองแลคตาซอย รสหวานคลาสสิค อร่อย หอมมัน อุดมไปด้วยโปรตีนและกรดอะมิโนจำเป็นจากถั่วเหลืองธรรมชาติ','uploads/lactasoy_original.png',100,''),(8,7,'เครื่องดื่มชาลิปตัน ไอซ์ที รสเลมอน (325 มล. x 6 กระป๋อง)',96.00,'ชาลิปตันไอซ์ที รสเลมอน เปรี้ยวหวานลงตัว หอมกลิ่นชาแท้และมะนาว สดชื่นกระปรี้กระเปร่าทันทีที่ดื่ม','uploads/lipton_ice_tea.png',80,''),(9,11,'เลย์ มันฝรั่งแท้ รสคลาสสิก 50 กรัม',20.00,'เลย์ มันฝรั่งทอดกรอบ รสคลาสสิก แผ่นเรียบ ผลิตจากมันฝรั่งแท้คุณภาพดี กรอบอร่อยเคี้ยวเพลิน','uploads/lays_classic.png',100,''),(10,7,'น้ำเก๊กฮวยธรรมชาติ ตราแฮนด์เมด (500 มล. x 6 ขวด)',90.00,'น้ำเก๊กฮวยสูตรต้มธรรมชาติ ดับกระหาย แก้ร้อนใน รสชาติหวานน้อยกลมกล่อมดีต่อสุขภาพ','uploads/chrysanthemum.png',85,''),(11,7,'เครื่องดื่มบำรุงกำลัง ตรากระทิงแดง (150 มล. x 10 ขวด)',120.00,'เครื่องดื่มบำรุงกำลังกระทิงแดง ให้พลังงานและความสดชื่นสไตล์ไทยดั้งเดิม เพิ่มประสิทธิภาพในการทำงานและออกกำลังกาย','uploads/red_bull_can.png',110,''),(12,7,'ปลาหมึกอบทรงเครื่อง ตราเบนโตะ Bento (20 กรัม x 12 ซอง)',240.00,'ปลาหมึกอบทรงเครื่อง ตราเบนโตะ รสเผ็ดจัดจ้าน อร่อยเต็มคำ เคี้ยวสนุกสไตล์วัยรุ่น','uploads/bento.png',100,''),(13,7,'นมเปรี้ยวพร้อมดื่ม ดัชมิลล์ รสผลไม้รวม (180 มล. x 4 กล่อง)',48.00,'นมเปรี้ยวโยเกิร์ตพร้อมดื่มดัชมิลล์ มีจุลินทรีย์โยเกิร์ตและวิตามินบี ช่วยระบบขับถ่ายและบำรุงร่างกาย','uploads/dutch_mill_yogurt.png',130,''),(14,8,'แป้งเย็นตรางู สูตรคลาสสิค (140 กรัม x 2 กระป๋อง)',75.00,'แป้งเย็นตรางู สูตรคลาสสิค ต้นตำรับแป้งเย็นที่ให้ความเย็นสดชื่น สบายผิว ช่วยลดผดผื่นคันที่เกิดจากอากาศร้อน','uploads/snake_brand.png',110,''),(15,8,'ครีมอาบน้ำส้มยูซุ สูตรผิวขาวกระจ่างใส (500 มล.)',189.00,'ครีมอาบน้ำสูตรส้มยูซุธรรมชาติ หอมสดชื่น ผ่อนคลายผิว บำรุงผิวให้เนียนนุ่มกระจ่างใสอย่างเป็นธรรมชาติ','uploads/yuzu_gel.png',90,''),(16,8,'ยาสีฟันคอลเกต รสยอดนิยม สูตรสตรอง คลีน (150 กรัม x 2 หลอด)',109.00,'ยาสีฟันคอลเกต ช่วยลดคราบแบคทีเรีย ป้องกันฟันผุและดูแลช่องปากอย่างยาวนาน เพื่อฟันแข็งแรงและลมหายใจหอมสดชื่น','uploads/colgate_toothpaste.png',130,''),(17,9,'น้ำยาล้างจาน ซันไลต์ เลมอนเทอร์โบ (500 มล. x 3 ถุง)',75.00,'ซันไลต์ เลมอนเทอร์โบ ขจัดคราบมันได้รวดเร็วขึ้น 5 ถุง ล้างภาชนะได้สะอาดหมดจด ปราศจากกลิ่นคาวและสารตกค้าง','uploads/sunlight_lemon.png',140,''),(18,12,'ผงซักฟอก บรีสเอกเซล 80 กรัม',10.00,'บรีส เอกเซล ผงซักฟอก สูตรเข้มข้น พลังซักสะอาดกระจายคราบลึก สะอาดหมดจดในขั้นตอนเดียว','uploads/breeze_excel.png',100,''),(19,10,'ยาธาตุน้ำขาว ตรากระต่ายบิน (200 มล.)',55.00,'ยาธาตุน้ำขาวตรากระต่ายบิน บรรเทาอาการปวดท้อง ท้องเสีย ท้องอืด ท้องเฟ้อ จุกเสียด แน่นท้อง ยาสามัญประจำบ้านยอดนิยม','uploads/flying_rabbit.png',120,''),(20,10,'ยาอมแก้ไอ บรรเทาอาการระคายคอ (กล่อง 20 ซอง)',260.00,'ยาอมสมุนไพรแก้ไอ ช่วยบรรเทาอาการระคายคอ ขับเสมหะ ลมหายใจสดชื่น พกพาสะดวก','uploads/cough_box.png',100,''),(21,12,'สมุดบันทึกปกหนังแท้พรีเมียม สไตล์วินเทจ',350.00,'สมุดบันทึกปกหนังแท้เนื้อดี กระดาษถนอมสายตาอย่างดี เหมาะสำหรับบันทึกความทรงจำ วางแผนงาน หรือวาดภาพสเก็ตช์','uploads/journal.png',70,''),(22,6,'ซอสสามเกลอ (กระเทียม,พริกไทย,ผักชี) อีซี่คุ๊ก',38.00,'ซอสปรุงรสแม็กกี้ ช่วยเพิ่มรสชาติและกลิ่นหอมชวนทานให้กับไข่ดาวและจานผัดต่างๆ (รหัสสินค้า: 8850125010376)','uploads/sam_kler_sauce.png',81,''),(23,6,'น้ำมันถั่วเหลือง',55.00,'น้ำมันถั่วเหลืองผ่านกรรมวิธี ตราองุ่น ปลอดภัย ไร้กลิ่นหืน เหมาะสำหรับจานผัดและทอด (รหัสสินค้า: 8850210000039)','uploads/soybean_oil.png',109,''),(24,7,'โค้ก รสออริจินัล 325 มล.',15.00,'เครื่องดื่มอัดลม โคคา-โคล่า รสชาติออริจินัล เย็นซ่า สดชื่น เหมาะสำหรับทุกช่วงเวลา','uploads/coke_original.png',100,''),(25,7,'เป๊ปซี่ เคลียร์ สูตรไม่มีน้ำตาล',17.00,'เครื่องดื่มน้ำอัดลม เป๊ปซี่ ซ่าสดชื่น เต็มรสชาติความซ่าในทุกช่วงเวลา (รหัสสินค้า: 8858998586349)','uploads/pepsi_zero.png',65,''),(26,7,'Milo',54.00,'ไมโล เครื่องดื่มช็อกโกแลตมอลต์ปรุงสำเร็จ มีโปรโตมอลต์และวิตามินแร่ธาตุสูง ให้พลังงานพร้อมลุยทุกกิจกรรม (รหัสสินค้า: 6111068000254)','uploads/milo_carton.png',59,''),(27,7,'Singha Drinking Water',60.00,'น้ำดื่มสิงห์ น้ำดื่มสะอาดบริสุทธิ์เพื่อสุขภาพที่ดีของทุกคนในครอบครัว บรรจุแพ็คละ 12 ขวด (รหัสสินค้า: 8850999320007)','uploads/singha_water.png',51,''),(28,7,'Nescafé Classic',125.00,'เนสกาแฟ เบลนด์ แอนด์ บรู กาแฟปรุงสำเร็จรูปชนิดผง หอมเข้มข้น กลมกล่อมลงตัวในทุกซอง (รหัสสินค้า: 6111018903161)','uploads/nescafe_classic.png',101,''),(29,8,'pond\' s',149.00,'พอนด์ส โฟมล้างหน้าเพื่อผิวกระจ่างใส ขจัดความหมองคล้ำและสิ่งสกปรกได้อย่างหมดจด (รหัสสินค้า: 7501056330262)','uploads/ponds_foam.png',119,''),(30,9,'Sterimar Hygiène',18.00,'ไฮยีน น้ำยาปรับผ้านุ่ม มอบสัมผัสผ้านุ่มละมุน กลิ่นหอมสดชื่นเป็นธรรมชาติ สวมใส่สบายตลอดทั้งวัน (รหัสสินค้า: 3331300097092)','uploads/sterimar_spray.png',113,'');
